@GameTestHolder(UnusualCopper.MOD_ID)
@PrefixGameTestTemplate(false)
public final class BrewerGameTests {
    private static void loaded(GameTestHelper h,int id,java.util.function.Consumer<BlockPos> test){var p=new BlockPos(110008+id*128,70,110008);PopulationGameTests.loaded(h,new WorkArea(p.offset(-7,0,-7),p.offset(8,15,8)),()->test.accept(p));}
    static CopperMachineBlockEntity machine(ServerLevel level,BlockPos pos){level.setBlock(pos,Blocks.AIR.defaultBlockState(),3);level.setBlock(pos,ModContent.MACHINES.get(MachineKind.AETHERIC_BREWER).get().defaultBlockState(),3);var m=(CopperMachineBlockEntity)level.getBlockEntity(pos);m.setOwner(UUID.randomUUID());m.energy.add(100000,false);m.brewer.pending=3;return m;}
    static void step(CopperMachineBlockEntity m,ServerLevel level){m.brewer.nextWork=0;BrewerLogic.process(m,level);}
    static BarrelBlockEntity chest(GameTestHelper h,CopperMachineBlockEntity m,BlockPos pos){var level=h.getLevel();level.setBlock(pos,Blocks.AIR.defaultBlockState(),3);level.setBlock(pos,Blocks.BARREL.defaultBlockState(),3);var player=FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(m.owner(),"BrewerOwner"));h.assertTrue(m.bind(pos,Direction.UP,player),"Owner binds an actual barrel");return(BarrelBlockEntity)level.getBlockEntity(pos);}
    private static int owned(CopperMachineBlockEntity m,net.minecraft.world.item.Item item){int count=0;for(int i=0;i<4;i++)if(m.inventory.getStackInSlot(i).is(item))count+=m.inventory.getStackInSlot(i).getCount();for(var stack:m.brewer.recovery.items())if(stack.is(item))count+=stack.getCount();if(m.brewer.job!=null&&m.brewer.job.current.is(item))count+=m.brewer.job.batch;for(var stack:m.boundCargo())if(stack.is(item))count+=stack.getCount();return count;}
    private static int potions(BarrelBlockEntity chest,ResourceLocation potion,int vessel){int count=0;for(int i=0;i<chest.getContainerSize();i++){var stack=chest.getItem(i);if(PotionPlans.vessel(stack)==vessel&&BuiltInRegistries.POTION.getKey(PotionUtils.getPotion(stack)).equals(potion))count+=stack.getCount();}return count;}
    @GameTest(template="empty",timeoutTicks=300)
    public static void graphUsesRealRecipesAndEveryAdvertisedStageMatchesForge(GameTestHelper h){
        var plans=PotionPlans.catalogue();h.assertTrue(plans.size()>60&&plans.size()<=512,"Bounded generated catalogue contains real reachable vanilla variants");
        for(var plan:plans){var current=PotionPlans.water();for(var step:plan.steps()){var actual=BrewingRecipeRegistry.getOutput(current.copy(),step.ingredient());h.assertTrue(ItemStack.isSameItemSameTags(actual,step.output()),"Actual Forge transition differs for "+plan.potion()+" vessel "+plan.vessel());current=actual;}h.assertTrue(ItemStack.isSameItemSameTags(current,plan.output()),"Entire real recipe chain reaches selected output");}
        var fire=PotionPlans.find(new ResourceLocation("minecraft","fire_resistance"),0);h.assertTrue(fire!=null&&fire.steps().size()==2&&BrewerLogic.costEach(fire)==5000,"Actual two-stage fire resistance costs five thousand per bottle");
        UnusualCopper.LOGGER.info("CuE BREWER GRAPH PASS: {} reachable exact variants; every advertised step verified against actual Forge BrewingRecipeRegistry",plans.size());h.succeed();
    }
    @GameTest(template="empty",timeoutTicks=300)
    public static void missingWartAndEnergyLeaveBottlesAndMaterialsUntouched(GameTestHelper h){loaded(h,0,p->{var level=h.getLevel();var m=machine(level,p);m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));step(m,level);h.assertTrue(m.brewer.job==null&&m.status()==MachineStatus.NEED_REAGENT&&m.inventory.getStackInSlot(0).getCount()==3&&m.energy.stored()==100000,"Missing nether wart cannot consume bottles or CuE");m.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));m.energy.restore(7499);step(m,level);h.assertTrue(m.brewer.job==null&&m.energy.stored()==7499&&m.inventory.getStackInSlot(1).getCount()==1,"One missing CuE leaves the complete first stage unchanged");m.energy.restore(7500);step(m,level);h.assertTrue(m.brewer.job!=null&&m.brewer.job.stage==1&&m.energy.stored()==0&&m.inventory.getStackInSlot(0).isEmpty()&&m.inventory.getStackInSlot(1).isEmpty()&&PotionUtils.getPotion(m.brewer.job.current)==Potions.AWKWARD,"Exactly 7500 CuE converts three real bottles plus one wart to three privately held awkward potions");});}
    @GameTest(template="empty",timeoutTicks=300)
    public static void intermediateSurvivesNbtAndCancelledJobReturnsActualPotions(GameTestHelper h){loaded(h,1,p->{var level=h.getLevel();var m=machine(level,p);m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));m.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));step(m,level);var saved=m.saveWithFullMetadata();m.load(saved);step(m,level);h.assertTrue(m.status()==MachineStatus.NEED_REAGENT&&m.brewer.job.stage==1&&m.energy.stored()==92500&&m.inventory.getStackInSlot(0).isEmpty(),"Reload preserves exact paid intermediate without regenerating bottles or wart");h.assertTrue(!m.getUpdateTag().contains("Brewer"),"Private potion escrow is not a public block update");BrewerLogic.cancel(m);h.assertTrue(m.brewer.job==null&&m.brewer.recovery.count()==3&&m.energy.stored()==92500&&m.brewer.recovery.items().stream().allMatch(s->PotionUtils.getPotion(s)==Potions.AWKWARD),"Cancel returns three actual intermediate potions, not original materials or paid CuE");});}
    @GameTest(template="empty",timeoutTicks=300)
    public static void outputOverflowKeepsEveryFinalBottleAndExactFullPrice(GameTestHelper h){loaded(h,2,p->{var level=h.getLevel();var m=machine(level,p);m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));m.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));step(m,level);m.inventory.setStackInSlot(1,new ItemStack(Items.MAGMA_CREAM));step(m,level);h.assertTrue(m.brewer.job==null&&m.brewer.pending==0&&m.energy.stored()==85000&&m.brewer.recovery.count()==3,"Three final bottles cost exactly 15000 total CuE and two reagents");m.inventory.setStackInSlot(2,new ItemStack(Items.STONE,64));m.inventory.setStackInSlot(3,new ItemStack(Items.STONE,64));step(m,level);h.assertTrue(m.status()==MachineStatus.OUTPUT_FULL&&m.brewer.recovery.count()==3&&m.energy.stored()==85000,"Full output keeps all real products in durable private storage");var saved=m.saveWithFullMetadata();m.load(saved);h.assertTrue(m.brewer.recovery.count()==3&&owned(m,Items.POTION)==3,"Full output escrow survives NBT without count truncation");});}
    @GameTest(template="empty",timeoutTicks=300)
    public static void realBoundBarrelBrewsSixteenWithSixVanillaReagentBatches(GameTestHelper h){loaded(h,3,p->{var level=h.getLevel();var m=machine(level,p);m.brewer.pending=16;var c=chest(h,m,p.east(4));c.setItem(0,new ItemStack(Items.GLASS_BOTTLE,16));c.setItem(1,new ItemStack(Items.NETHER_WART,6));c.setItem(2,new ItemStack(Items.MAGMA_CREAM,6));for(int i=0;i<300;i++){step(m,level);BoundStorageLogic.tick(m,level);}h.assertTrue(potions(c,m.brewer.potion,0)==16&&m.energy.stored()==20000&&m.brewer.pending==0&&m.brewer.job==null&&m.brewer.recovery.empty()&&m.boundCargoCount()==0,"Actual physical barrel receives sixteen exact potions for 80000 CuE");int inputs=0;for(int i=0;i<c.getContainerSize();i++)if(c.getItem(i).is(Items.GLASS_BOTTLE)||c.getItem(i).is(Items.NETHER_WART)||c.getItem(i).is(Items.MAGMA_CREAM))inputs+=c.getItem(i).getCount();h.assertTrue(inputs==0&&owned(m,Items.GLASS_BOTTLE)==0&&owned(m,Items.NETHER_WART)==0&&owned(m,Items.MAGMA_CREAM)==0,"Sixteen glass bottles and six of each reagent were physically consumed in vanilla batches 3/3/3/3/3/1");});}
    @GameTest(template="empty",timeoutTicks=300)
    public static void twoMaintainMachinesReserveOneSharedMissingBatch(GameTestHelper h){loaded(h,4,p->{var level=h.getLevel();var first=machine(level,p);var second=machine(level,p.south(2));second.setOwner(first.owner());chest(h,first,p.east(4));var c=chest(h,second,p.east(4));
        first.brewer.maintain=second.brewer.maintain=true;first.brewer.pending=second.brewer.pending=3;
        for(var m:List.of(first,second)){m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));m.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));BrewerScheduler.register(level,m);}
        step(first,level);step(second,level);h.assertTrue(first.brewer.job!=null&&second.brewer.job==null&&second.status()==MachineStatus.STOCK_REACHED&&second.energy.stored()==100000,"Neighbor observes the first admitted batch before products arrive and cannot overproduce");
        first.inventory.setStackInSlot(1,new ItemStack(Items.MAGMA_CREAM));for(int i=0;i<30;i++){step(first,level);BoundStorageLogic.tick(first,level);step(second,level);BoundStorageLogic.tick(second,level);}h.assertTrue(potions(c,first.brewer.potion,0)==3&&second.energy.stored()==100000,"Shared target reaches three, not six, after actual insertion");
        });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void stockCountDistinguishesPotionNbtAndSharedFaces(GameTestHelper h){loaded(h,8,p->{var level=h.getLevel();var m=machine(level,p);m.brewer.maintain=true;m.brewer.pending=3;var c=chest(h,m,p.east(4));for(int i=0;i<3;i++)c.setItem(i,PotionUtils.setPotion(new ItemStack(Items.POTION),Potions.LONG_FIRE_RESISTANCE));m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));m.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));step(m,level);h.assertTrue(m.brewer.job!=null&&m.brewer.job.batch==3&&m.energy.stored()==92500,"Three long fire-resistance bottles do not satisfy a normal fire-resistance stock target with the same item ID");var saved=m.saveWithFullMetadata();m.load(saved);h.assertTrue(m.duration==2&&m.progress==1&&m.operationCost==7500,"Generic menu progress/cancel state is restored from the durable job before any next tick");
        var neighbor=machine(level,p.south(2));neighbor.setOwner(m.owner());neighbor.brewer.maintain=true;neighbor.brewer.pending=3;var actor=FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(m.owner(),"SharedFaceBrewer"));h.assertTrue(neighbor.bind(p.east(4),Direction.DOWN,actor),"Neighbor binds the same actual barrel through a different face");neighbor.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));neighbor.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));step(neighbor,level);h.assertTrue(neighbor.brewer.job==null&&neighbor.status()==MachineStatus.STOCK_REACHED&&neighbor.energy.stored()==100000,"A different face cannot hide the existing admitted normal-potion batch from shared stock accounting");
    });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void changedOrThrowingForgeRecipeCannotConsumeInputsOrEnergy(GameTestHelper h){loaded(h,7,p->{var level=h.getLevel();var m=machine(level,p);m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));m.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));
        var mode=new boolean[]{false};var probe=new net.minecraftforge.common.brewing.IBrewingRecipe(){public boolean isInput(ItemStack input){return true;}public boolean isIngredient(ItemStack input){return true;}public ItemStack getOutput(ItemStack input,ItemStack ingredient){if(mode[0])throw new IllegalStateException("Intentional brewing provider failure");return new ItemStack(Items.DIAMOND);}};
        try{var field=BrewingRecipeRegistry.class.getDeclaredField("recipes");field.setAccessible(true);@SuppressWarnings("unchecked")var recipes=(List<net.minecraftforge.common.brewing.IBrewingRecipe>)field.get(null);recipes.add(0,probe);
            try{step(m,level);h.assertTrue(m.status()==MachineStatus.RECIPE_CHANGED&&m.energy.stored()==100000&&m.inventory.getStackInSlot(0).getCount()==3&&m.inventory.getStackInSlot(1).getCount()==1,"Real Forge output drift preserves every real input and CuE");mode[0]=true;step(m,level);h.assertTrue(m.brewer.faulted&&m.status()==MachineStatus.BREW_FAULT&&m.energy.stored()==100000&&m.inventory.getStackInSlot(0).getCount()==3,"Throwing provider faults safely before extraction or charging");var saved=m.saveWithFullMetadata();m.load(saved);h.assertTrue(m.brewer.faulted&&m.brewer.job!=null&&m.brewer.job.current.isEmpty(),"Faulty uncommitted job survives NBT without minting a potion");BrewerLogic.cancel(m);h.assertTrue(m.brewer.recovery.empty()&&!m.brewer.faulted&&m.brewer.pending==0,"Cancel recovers the uncommitted job without inventing an intermediate");}
            finally{recipes.remove(probe);}
        }catch(ReflectiveOperationException error){throw new IllegalStateException("Fixture could not reach the actual Forge recipe list",error);}
        m.brewer.pending=3;step(m,level);h.assertTrue(m.brewer.job!=null&&m.brewer.job.stage==1&&m.energy.stored()==92500,"Restored actual Forge recipe can resume after explicit new order");
    });}
    @GameTest(template="empty",timeoutTicks=300)
    public static void settingsRejectStaleForeignMalformedAndBusyEdits(GameTestHelper h){loaded(h,6,p->{var level=h.getLevel();var m=machine(level,p);var owner=FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(m.owner(),"BrewerEditor"));owner.setPos(p.getX()+.5,p.getY()+.5,p.getZ()+.5);
        var values=new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Settings(new ResourceLocation("minecraft","long_fire_resistance"),2,16,true,7);var menu=new io.github.gerbesh.unusualcopper.menu.BrewerMenu(7,owner.getInventory(),m);
        h.assertTrue(menu.configure(m.runtimeIdentity,values,owner)&&m.brewer.vessel==2&&m.brewer.pending==16&&m.brewer.priority==7&&m.brewer.maintain,"Nearby owner applies an exact real potion/container/count/mode/priority");var before=m.brewer.save();
        h.assertTrue(!menu.configure(m.runtimeIdentity,values,owner)&&before.equals(m.brewer.save()),"Same-tick duplicate cannot restart a valid order");
        var preview=new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Inspect(7,m.runtimeIdentity,new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Settings(new ResourceLocation("minecraft:swiftness"),0,64,false,0),List.of(new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Key(new ResourceLocation("minecraft:swiftness"),0)));
        h.assertTrue(menu.inspect(preview,owner)&&before.equals(m.brewer.save())&&m.energy.stored()==100000,"Browsing another recipe never changes the saved order or charges energy");
        h.assertTrue(!menu.inspect(preview,owner)&&before.equals(m.brewer.save()),"Repeated inspection is bounded without changing production");
        var stalePreview=new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Inspect(8,UUID.randomUUID(),preview.preview(),preview.visible());
        h.assertTrue(!new io.github.gerbesh.unusualcopper.menu.BrewerMenu(8,owner.getInventory(),m).inspect(stalePreview,owner)&&before.equals(m.brewer.save()),"A replacement block cannot receive a stale recipe preview");
        var invalid=List.of(new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Settings(new ResourceLocation("minecraft","not_a_potion"),0,3,false,0),new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Settings(values.potion(),3,3,false,0),new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Settings(values.potion(),0,0,false,0),new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Settings(values.potion(),0,4097,false,0),new io.github.gerbesh.unusualcopper.network.BrewerNetwork.Settings(values.potion(),0,3,false,10));
        for(var setting:invalid)h.assertTrue(!new io.github.gerbesh.unusualcopper.menu.BrewerMenu(8,owner.getInventory(),m).configure(m.runtimeIdentity,setting,owner)&&before.equals(m.brewer.save()),"Invalid options preserve all saved settings");
        h.assertTrue(!new io.github.gerbesh.unusualcopper.menu.BrewerMenu(9,owner.getInventory(),m).configure(UUID.randomUUID(),values,owner),"A stale block runtime token cannot edit a replacement");var stranger=FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"ForeignBrewer"));stranger.setPos(owner.position());h.assertTrue(!new io.github.gerbesh.unusualcopper.menu.BrewerMenu(10,stranger.getInventory(),m).configure(m.runtimeIdentity,values,stranger),"Foreign player cannot edit the order");
        m.brewer.maintain=false;m.brewer.pending=3;m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));m.inventory.setStackInSlot(1,PotionPlans.find(m.brewer.potion,2).steps().get(0).ingredient());step(m,level);var active=m.brewer.save();h.assertTrue(!new io.github.gerbesh.unusualcopper.menu.BrewerMenu(11,owner.getInventory(),m).configure(m.runtimeIdentity,values,owner)&&active.equals(m.brewer.save()),"Started batch keeps its immutable recipe and quote");
        owner.setPos(p.getX()+20,p.getY(),p.getZ());h.assertTrue(!new io.github.gerbesh.unusualcopper.menu.BrewerMenu(12,owner.getInventory(),m).configure(m.runtimeIdentity,values,owner),"Distant owner cannot edit the machine");
    });}
    @GameTest(template="empty",timeoutTicks=600)
    public static void actualSchedulerHonorsPriorityStageDelayAndSharedStock(GameTestHelper h){
        var p=new BlockPos(111032,70,110008);var state=new Object(){CopperMachineBlockEntity low,high;BarrelBlockEntity chest;long firstStage;};
        PopulationGameTests.loadedSequence(h,new WorkArea(p.offset(-7,0,-7),p.offset(8,15,8)),seq->seq.thenExecute(()->{
            var level=h.getLevel();state.low=machine(level,p);state.high=machine(level,p.south(2));state.high.setOwner(state.low.owner());chest(h,state.low,p.east(4));state.chest=chest(h,state.high,p.east(4));state.chest.setItem(0,new ItemStack(Items.MAGMA_CREAM));
            for(var m:List.of(state.low,state.high)){m.brewer.maintain=true;m.brewer.pending=3;m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));m.inventory.setStackInSlot(1,new ItemStack(Items.NETHER_WART));}state.high.brewer.priority=9;
        }).thenWaitUntil(()->h.assertTrue(state.high.brewer.job!=null&&state.high.brewer.job.stage==1,"High priority real queued batch has completed its first stage")).thenExecute(()->{
            h.assertTrue(state.low.brewer.job==null&&state.low.energy.stored()==100000&&state.high.energy.stored()==92500,"Priority nine reserves the shared missing batch before priority zero");state.firstStage=h.getLevel().getGameTime();
        }).thenWaitUntil(()->h.assertTrue(state.high.grown==3,"Real ticker completed the second stage")).thenExecute(()->h.assertTrue(h.getLevel().getGameTime()-state.firstStage>=20,"Actual committed stages are separated by at least twenty ticks")).thenWaitUntil(()->h.assertTrue(state.high.status()==MachineStatus.STOCK_REACHED,"Actual stock delivery finished")).thenExecute(()->{
            h.assertTrue(potions(state.chest,state.high.brewer.potion,0)==3&&state.high.energy.stored()==85000&&state.low.energy.stored()==100000&&state.low.inventory.getStackInSlot(0).getCount()==3&&state.low.inventory.getStackInSlot(1).is(Items.NETHER_WART),"Real scheduler, physical input/output and neighbor reservation conserve every item and fee");state.low.redstoneMode=state.high.redstoneMode=1;
        }));
    }
    @GameTest(template="empty",timeoutTicks=300)
    public static void lingeringChainReturnsDragonBreathBottleWithoutChangingOutput(GameTestHelper h){loaded(h,5,p->{var level=h.getLevel();var m=machine(level,p);m.brewer.vessel=2;var plan=PotionPlans.find(m.brewer.potion,2);m.inventory.setStackInSlot(0,new ItemStack(Items.GLASS_BOTTLE,3));int bottles=0;for(var recipe:plan.steps()){m.inventory.setStackInSlot(1,recipe.ingredient());step(m,level);if(!m.brewer.recovery.empty()){for(var held:m.brewer.recovery.items())if(held.is(Items.GLASS_BOTTLE))bottles+=held.getCount();}}
        h.assertTrue(m.brewer.job==null&&m.energy.stored()==100000-3*BrewerLogic.costEach(plan)&&owned(m,Items.LINGERING_POTION)==3&&bottles==1,"Actual lingering chain preserves three exact products and the one real dragon-breath container");});}
}
